<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import Modal from '../work/Modal.vue';
const emit=defineEmits<{close:[]}>();
type Row={id:number;timestamp:string;actorName:string;action:string;entityType:string;entityId:number|null;result:string;note:string};
const data=ref<{items:Row[];total:number;pageSize:number}>({items:[],total:0,pageSize:50}),page=ref(1),search=ref(''),from=ref(''),to=ref(''),action=ref(''),busy=ref(false),error=ref('');
const actions:Record<string,string>={CREATE:'Создание',UPDATE:'Изменение',DELETE:'Удаление',RESTORE:'Восстановление',ASSIGN:'Назначение исполнителя',COMPLETE:'Завершение работы',START:'Начало работы',APPLY:'Применение шаблона',VIEW:'Просмотр',DOWNLOAD:'Скачивание документа',EXPORT:'Экспорт Excel',EXPORT_PREPARE:'Подготовка выгрузки',EXPORT_CONFIRM:'Запуск выгрузки',EXPORT_READY:'Архив готов',EXPORT_DOWNLOAD:'Скачивание ZIP',EXPORT_CANCEL:'Отмена выгрузки',EXPORT_FAILED:'Ошибка выгрузки',COMMENT:'Комментарий',MEMBER:'Участники'};
const entities:Record<string,string>={UptsContract:'Объект',WorkTask:'Работа',WorkProjectFile:'Документ',UptsExport:'Выгрузка',WorkProject:'Проект',UptsWorkDefinition:'Библиотека работ',UptsWorkTemplate:'Шаблон работ'};
let controller:AbortController|undefined,serial=0;
async function load(reset=false){if(reset)page.value=1;const n=++serial;controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{const result=await $fetch<typeof data.value>('/api/upts/events',{query:{page:page.value,search:search.value,from:from.value,to:to.value,action:action.value},signal:controller.signal});if(n===serial)data.value=result;}catch(e:any){if(n===serial)error.value=e.data?.message||'Не удалось загрузить журнал.';}finally{if(n===serial)busy.value=false;}}
const when=(s:string)=>new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'medium'}).format(new Date(s));
onMounted(()=>load());onBeforeUnmount(()=>{serial++;controller?.abort();});
</script>
<template><Modal title="Журнал событий УПТС" icon="lucide:list" full-height viewport-width fixed-sections grey-header @close="emit('close')"><div class="upts-journal">
 <form class="work-toolbar" @submit.prevent="load(true)"><label>С даты<input v-model="from" type="date" /></label><label>По дату<input v-model="to" type="date" /></label><label>Действие<select v-model="action"><option value="">Все действия</option><option v-for="(label,key) in actions" :key="key" :value="key">{{ label }}</option></select></label><label>Поиск<input v-model="search" maxlength="200" placeholder="Пользователь или событие" /></label><button :disabled="busy">Показать</button></form>
 <p class="work-muted">События доступных вам объектов и ваши выгрузки. Полный журнал доступен уполномоченным пользователям в центре администрирования.</p><p v-if="error" class="work-error" role="alert">{{ error }}</p><p v-if="busy" role="status">Загружаем журнал…</p>
 <div class="work-table-wrap journal-table"><table><thead><tr><th>Дата и время (МСК)</th><th>Пользователь</th><th>Действие</th><th>Запись</th><th>Событие</th><th>Результат</th></tr></thead><tbody><tr v-for="r in data.items" :key="r.id"><td>{{ when(r.timestamp) }}</td><td>{{ r.actorName }}</td><td>{{ actions[r.action]||r.action }}</td><td>{{ entities[r.entityType]||r.entityType }} {{ r.entityId?'#'+r.entityId:'' }}</td><td>{{ r.note }}</td><td>{{ r.result==='SUCCESS'?'Успешно':r.result==='DENIED'?'Отказано':'Ошибка' }}</td></tr><tr v-if="!busy&&!data.items.length"><td colspan="6">Событий нет.</td></tr></tbody></table></div>
 <footer class="work-actions"><span>Всего: {{ data.total }} · Страница {{ page }}</span><button :disabled="busy||page<=1" @click="page--;load()">Назад</button><button :disabled="busy||page*data.pageSize>=data.total" @click="page++;load()">Далее</button><button @click="emit('close')">Закрыть</button></footer>
</div></Modal></template>
<style scoped>.upts-journal{height:100%;min-height:0;display:flex;flex-direction:column;gap:10px}.upts-journal .work-toolbar{margin:0;justify-content:flex-start;align-items:end}.journal-table{flex:1;min-height:0;overflow:auto}.journal-table table{width:100%}.journal-table :is(td,th){padding:7px;font-size:12px;text-align:left;border-bottom:1px solid var(--work-line)}.journal-table th{position:sticky;top:0;background:var(--work-panel)}.upts-journal p{margin:0}.upts-journal footer{flex-shrink:0}</style>
